import mongoose from 'mongoose';

// The app keeps two models: User and Document. Optimized versions live inside their
// document (`versions`), so a document and its whole revision history are read and
// authorized together. The original text is immutable once saved.

export const STATUSES = ['draft', 'analyzed', 'awaiting_review', 'approved', 'rejected'];
export const MAX_VERSIONS = 50;

const versionSchema = new mongoose.Schema(
  {
    text: { type: String, required: true },
    // optimizer = generated by "Optimize Content"; edit = saved by the user from the comparison page
    source: { type: String, enum: ['optimizer', 'edit'], required: true },
    analysis: { type: mongoose.Schema.Types.Mixed, required: true },
    changes: { type: [mongoose.Schema.Types.Mixed], default: [] },
    createdAt: { type: Date, default: Date.now },
  },
  { _id: true }
);

const documentSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    title: { type: String, required: true, trim: true, maxlength: 200 },
    sourceType: { type: String, enum: ['file', 'url', 'text'], required: true },
    sourceName: { type: String, default: '' }, // file name or URL
    originalText: { type: String, required: true, immutable: true },
    originalAnalysis: { type: mongoose.Schema.Types.Mixed, default: null },

    versions: { type: [versionSchema], default: [] },
    currentVersionId: { type: mongoose.Schema.Types.ObjectId, default: null },

    status: { type: String, enum: STATUSES, default: 'draft' },
    approvedVersionId: { type: mongoose.Schema.Types.ObjectId, default: null },
    approvedAt: { type: Date, default: null },
    reviewedAt: { type: Date, default: null },

    // Copied from the analyses so the document list does not have to load every version.
    scores: {
      originalGrammar: { type: Number, default: null },
      originalReadability: { type: Number, default: null },
      optimizedGrammar: { type: Number, default: null },
      optimizedReadability: { type: Number, default: null },
    },
    wordCount: { type: Number, default: 0 },
  },
  { timestamps: true, versionKey: '__v', optimisticConcurrency: true }
);

documentSchema.index({ user: 1, updatedAt: -1 });
documentSchema.index({ user: 1, status: 1 });

documentSchema.methods.currentVersion = function currentVersion() {
  return this.currentVersionId ? this.versions.id(this.currentVersionId) : null;
};

export default mongoose.model('Document', documentSchema);
